# PyTorch-style sketch (snnTorch, Norse and SpikingJelly provide ready-made versions)
class Spike(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):            # x = U - theta
        ctx.save_for_backward(x)
        return (x > 0).float()
    @staticmethod
    def backward(ctx, grad):
        (x,) = ctx.saved_tensors
        return grad / (1 + beta * x.abs()) ** 2   # fast-sigmoid surrogate

for t in range(T):
    U = decay * U + fc(inp[t]) - S * theta    # LIF with reset by subtraction
    S = Spike.apply(U - theta)
    out_spikes.append(S)
loss = criterion(torch.stack(out_spikes).sum(0), target)   # e.g. spike-count cross-entropy
loss.backward(); optimizer.step()
